// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        Reverter caller = new Reverter();
        vm.deal(address(caller), amount);
        vm.prank(address(caller));
        c.addToBalance{value: amount}();
        uint256 balBefore = address(c).balance;
        vm.prank(address(caller));
        bool ok;
        try c.withdrawBalance() { ok = true; } catch { ok = false; }
        assertTrue(!ok || address(c).balance == balBefore - amount);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
